import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Tag } from "../../../components/ui";
import api from "../../../services/api";
import { parseApiError, getUserEmail } from "../../../services/auth";
import { listApplications } from "../../../services/applicationsApi";

export default function ProfessionalDashboardHome() {
  const navigate = useNavigate();
  const [recent, setRecent] = useState([]);
  const [applicationCount, setApplicationCount] = useState(0);
  const [offersCount, setOffersCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const displayName = getUserEmail()?.split("@")[0] || "there";

  useEffect(() => {
    let cancelled = false;
    const loadDashboard = async () => {
      try {
        const [dashboardRes, profileRes] = await Promise.all([
          api.get("/dashboard/"),
          api.get("/profile/me/").catch(() => null),
        ]);
        if (cancelled) return;

        setRecent((dashboardRes.data?.recent_announcements || []).slice(0, 3));

        if (profileRes?.data?.id) {
          const profileId = profileRes.data.id;
          const apps = await listApplications({ applicant: profileId });
          if (cancelled) return;
          setApplicationCount(apps.length);
          setOffersCount(apps.filter((app) => app.status === "ACCEPT").length);
        }
      } catch (err) {
        if (cancelled) return;
        setError(parseApiError(err, "Unable to load dashboard details."));
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    loadDashboard();
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div>
      {/* Premium Navy Welcome Card */}
      <div className="bg-[#0B1E36] rounded-3xl p-8 mb-8 text-white relative overflow-hidden shadow-lg hover:shadow-xl transition-all duration-300">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-16 -mt-16 blur-2xl pointer-events-none" />

        <div className="relative z-10">
          <p className="text-2xl font-serif italic text-white tracking-wide mb-2">
            Professional
          </p>
          <h1 className="text-3xl md:text-4xl font-light text-slate-200">
            hey <span className="italic font-normal text-white">{displayName}</span>
          </h1>
        </div>
      </div>

      {/* Dynamic Statistics Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
        {[
          { label: "Applications sent", value: String(applicationCount), color: "text-blue-600", desc: "Active submissions" },
          { label: "Offers received", value: String(offersCount), color: "text-emerald-600", desc: "Accepted status" },
          { label: "Active Search", value: "On", color: "text-[#1b3a5c]", desc: "Visible to employers" },
        ].map((s) => (
          <div key={s.label} className="bg-white rounded-3xl p-6 border border-gray-150/50 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all duration-300">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2">{s.label}</p>
            <p className={`font-serif text-4xl font-normal ${s.color} mb-1`}>{s.value}</p>
            <p className="text-[10px] text-gray-400 font-medium">{s.desc}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Recent Announcements */}
        <div className="lg:col-span-2 bg-white rounded-3xl p-6 border border-gray-150/50 shadow-sm flex flex-col">
          <div className="flex justify-between items-center mb-5">
            <h2 className="font-semibold text-gray-900">Recent announcements</h2>
            <button
              type="button"
              onClick={() => navigate("/professional/dashboard/announcements")}
              className="px-4 py-2 border border-gray-200 rounded-full text-xs hover:bg-gray-50 transition-colors cursor-pointer"
            >
              View all
            </button>
          </div>

          <div className="flex flex-col gap-3 flex-1">
            {loading ? (
              <p className="text-sm text-gray-400">Loading announcements...</p>
            ) : error ? (
              <p className="text-sm text-red-600">{error}</p>
            ) : recent.length === 0 ? (
              <p className="text-sm text-gray-400">No active announcements available yet.</p>
            ) : (
              recent.map((job) => (
                <button
                  key={job.id}
                  type="button"
                  onClick={() => navigate(`/professional/dashboard/announcements/${job.id}`)}
                  className="flex items-center justify-between p-4 border border-gray-100 rounded-2xl hover:bg-gray-50 transition-all text-left cursor-pointer"
                >
                  <div>
                    <p className="font-semibold text-sm text-gray-900">{job.role}</p>
                    <p className="text-xs text-gray-400 mt-0.5">
                      {job.enterprise_name} · {job.wilaya}
                    </p>
                  </div>
                  <div className="flex gap-2 flex-shrink-0">
                    <Tag variant="new">{job.job_type}</Tag>
                    <Tag variant="remote">{job.status}</Tag>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Quick Tools Box */}
        <div className="bg-white rounded-3xl p-6 border border-gray-150/50 shadow-sm flex flex-col gap-4">
          <h2 className="font-semibold text-gray-900 text-base mb-1">Quick Tools</h2>

          <button
            type="button"
            onClick={() => navigate("/professional/dashboard/profile")}
            className="w-full flex items-center justify-between p-3.5 border border-gray-100 rounded-2xl hover:bg-slate-50 transition-all text-left cursor-pointer"
          >
            <div>
              <p className="font-semibold text-xs text-gray-800">Edit Profile Info</p>
              <p className="text-[10px] text-gray-400">Keep your certifications up to date</p>
            </div>
            <span className="text-xs text-gray-400">➔</span>
          </button>

          <button
            type="button"
            onClick={() => navigate("/professional/dashboard/settings")}
            className="w-full flex items-center justify-between p-3.5 border border-gray-100 rounded-2xl hover:bg-slate-50 transition-all text-left cursor-pointer"
          >
            <div>
              <p className="font-semibold text-xs text-gray-800">Account Settings</p>
              <p className="text-[10px] text-gray-400">Configure notifications and security</p>
            </div>
            <span className="text-xs text-gray-400">➔</span>
          </button>

          <div className="mt-2 pt-4 border-t border-gray-100 flex-1 flex flex-col justify-end">
            <div className="p-4 bg-amber-500/5 border border-amber-500/10 rounded-2xl">
              <p className="text-xs font-semibold text-amber-800 mb-1">ℹ Verification Status</p>
              <p className="text-[10px] text-amber-700 leading-relaxed font-medium">
                Your <em className="italic">Professional</em> designation is active and verified by our auditing team.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
